"""One registry of named craft guidance, and the tool profiles a host application offers its model.

``vixl_reference(NAME)``, ``vixl_reference('guidance', name=NAME)``, ``vixl_reference``,
the guidance names a ``vixl_reference`` kind points at and the ``guidance`` that ``vixl_reference('capabilities')`` lists
all read ``GUIDANCE``; user additions (``vixl_apply(workflow='resource-save')``) join it through ``resources.catalog``.

Motif knowledge (the concrete things a brief implies and what draws them) is data in ``data/motifs.json``,
read only here: ``motifs(brief)`` gives the themes a brief matches, which ``vixl_reference`` returns as ``motifs``.
"""

from functools import lru_cache
import json
from pathlib import Path
import re
import unicodedata

MOTIFS_FILE = Path(__file__).resolve().parent / "data" / "motifs.json"

GUIDANCE = {
    "motifs": "Draw the specific thing the brief names, not a placeholder: a cup with steam rather than a disc, a lighthouse standing in filled layered water rather than on a bar, strung lanterns with glows rather than dots on a line, an irregular lit skyline rather than equal boxes, reflections that mirror the scene rather than dashes. vixl_reference(brief) lists the motifs a brief implies with the catalog shapes, organic presets, object kinds and operations (string-lights, star-field, haze, reflection, bokeh, organic preset water) that draw them; vixl_reference('motifs') lists every theme. Make the motif specific by asking three questions before drawing, and answer each with a drawn element: what is the object (the one thing the brief names, with the detail that identifies it: a cup's steam, a leaf's veins, a ball's seams, a balloon's knot and string)? what does it emit or reflect (steam, a glow, light on the page, motion lines, a shadow, a reflection in water)? what frames it (the place that holds it: a shelf, a window, a horizon, a pot, a field, a border)? Each theme in vixl_reference('motifs') lists its answers. Catalog shapes draw the objects that composed shapes draw badly (cup, steam, lighthouse, lantern, microphone, snowflake, leaf, book, balloon), and haze with form fog lays stacked soft bands of mist behind the layers you name. Give the motif one focal place, keep decoration clear of the copy, and check the preview at delivery size: if a shape could be anything, add the detail that names it.",
    "overall": "Choose a clear hierarchy, align related elements, use consistent spacing, preserve readable contrast, inspect at delivery size, and measure before exporting.",
    "minimal": "Use generous negative space, a small palette, few type sizes, and a single focal point. Prefer simple geometry and deliberate alignment.",
    "editorial": "Establish headline, body and caption hierarchy. Use a coherent grid, restrained accents, and consistent margins. Keep body text readable.",
    "playful": "Use energetic accents and rounded forms while preserving hierarchy, contrast, and consistent spacing.",
    "meme": "Memes are layouts plus your own pictures: layout-apply meme-top-bottom, meme-caption-above, meme-comparison, meme-labelled, meme-reaction or meme-four-panel, with image (or images, one per panel) set to assets you have the rights to use; Vixl ships no meme images. Keep captions to a few words: stroked captions are uppercase, white with a black stroke, and shrink to fit their box (uppercase=false keeps the case). For the Impact look install an OFL condensed face, e.g. {type: font-install, family: Anton, role: heading} in vixl_apply, or display_font, never a non-OFL font. Check, preview at phone size, export PNG or JPEG. GIF: start from meme-reaction, animate the caption (animate-preset pop-in or shake, or motion), preview with vixl_render(action='timeline') and export with vixl_export(kind='timeline') to .gif (keep it short, 2-4 s, and loop).",
    "logo": "Start on a transparent canvas. Use simple silhouettes, test small sizes and monochrome, and export SVG when scalable geometry is needed.",
    "pixel-art": "Use an intentional limited palette, integer positions and crisp nearest-neighbor exports. Keep sprite timing and silhouettes readable. New sprites draw with a shading ramp and a 1 px outline; give a large area some form rather than one flat colour.",
    "typography": "Pick a pairing before placing text (vixl font pairings; font pair NAME), never ship the proofing fallback, and use one or two families with fixed roles: contrast in classification or a superfamily, matched x-heights, heading 600–800 over body 400. Use a modular type scale (type-scale). Keep body lines 45–75 characters, line height about 1.4 for body and 1.1 for headlines, and create hierarchy with size and weight before color. Align text to a shared edge.",
    "color": "Assign roles before picking hues: background, surface, ink, muted, accent. Keep body text at 4.5:1 or better, large text and graphics at 3:1, and use the accent sparingly for the one thing that matters. Check designs with color-vision simulation; never rely on hue alone.",
    "layout": "Start from a grid or a proportional system (thirds, golden section, modular columns). Give each piece of content one job, group related items by proximity, align to edges, keep consistent margins on a spacing unit, and leave space empty on purpose. Let a stack (auto-layout, the CSS flexbox and grid model) place rows, columns and grids instead of computing positions, and adapt-layout carry the design to other sizes.",
    "stacks": "A stack is CSS flexbox and grid for a group: {type: stack, name, targets} or {type: stack, target: GROUP}. direction is flex-direction (vertical = column, horizontal = row) or grid; gap is gap and row_gap is row-gap (pixels or units such as 2u); justify is justify-content (start, center, end, space-between, space-around, space-evenly); align is align-items (start, center, end, stretch: text wraps to the box width, shapes and frames fill it); wrap is flex-wrap for rows; grow {member: weight} is flex-grow; columns is grid-template-columns (a count, or ['1fr', '2fr'] or [240, '1fr']) and span {member: n} is grid-column: span n; size hug is fit-content; padding is padding. The CSS spellings (justify_content, align_items, flex_wrap, flex_grow, grid_template_columns, row/column) are accepted and reported as the field they map to. Members re-flow whenever text changes or empties (hide_if_empty), at export time too, and cannot be moved by hand: change the stack. Use space-between for a header or footer row, a hug stack with padding for a button, stretch for full-width rules and cards, a grid with span for a feature grid. Stacked layouts also adapt cleanly: adapt-layout rebuilds a layout-apply design at a new size unless it was edited, and arrangements re-place other documents (stack-vertical, side-by-side, hero-top) and keep the one the checks score best.",
    "accessibility": "Meet WCAG contrast (4.5:1 text, 3:1 large text and UI), keep text at legible sizes for the delivery medium, never encode meaning only in color, and keep important content inside safe areas. Set the language ({type: accessibility, lang: 'en-GB'}; page_lang for a page in another language), describe every meaningful image, frame, chart, link or object group with layer-intent alt (mark ornaments decorative: true), give a deck's pages a reading order where top-to-bottom is wrong (accessibility reading_order), and run vixl_check(checks=[accessibility]) before exporting HTML, PDF, PowerPoint or SVG: it bundles contrast and colour vision with missing alt text, language, small text, colour-only charts and reading order. Exports carry alt and language (HTML alt/lang, SVG title and role, PowerPoint descr and decorative, PDF /Alt and /Lang); a tagged PDF structure tree is not written.",
    "print": "Design at the final physical size and resolution (300 dpi for most print). Extend backgrounds into the bleed, keep text inside the safe (live) area, keep total ink coverage under about 300%, avoid type below 6 pt, and export CMYK with the printer's ICC profile when one is provided.",
    "icon": "Build on a square grid with a central keyline area, use one recognizable silhouette, test at 16–32 px and in monochrome, avoid fine detail and text, and export every required size from one master.",
    "motion": "Animate to explain, not decorate. Use 150–500 ms for interface-scale moves and up to about 1 s for entrances, ease out when entering and ease in when leaving, stagger related elements, and keep a still frame that reads on its own.",
    "image-rights": "Use an image from the web only when you have the right to: your own or the client's work, a stated license (Creative Commons, Unsplash, Pexels, public domain) or written permission. Import it with url= so the layer records the source URL, fetch time and sha256, and pass credit and license (e.g. credit 'Photo: Ana Ruiz / Unsplash', license 'CC BY 4.0'); inspect shows them and dependencies lists them as attributions. Honour license terms: CC BY needs visible credit, NC forbids commercial use, ND forbids edits. When rights are unclear, use a placeholder frame or a generated image instead, and never strip a watermark.",
    "charts": "Use chart for any bar, line, area, pie or donut instead of drawing shapes and computing heights, totals and shares yourself: give the data once (categories + series, table, or a workspace csv) and the chart is a group of ordinary vector layers bound to it. Edit numbers with chart-data (set, append, add_series, remove_series, reload) so layer IDs survive; restyle with chart and target, never by moving its NAME/part layers. table and table-data do the same for tables, key-value-list for label / value / share rows on shared right edges (a summary beside a chart, a price list). Colours and fonts come from the document (palette, @accent, heading/body roles); set number_format once for ticks, labels and the PPTX chart. Pick the form for the question: bars compare categories, lines show change over time, pie or donut only a few parts of one whole; label values directly (value_labels: auto) rather than relying on a legend, and never encode meaning in hue alone. Inspect the chart for chart.summary (totals, shares, scale); check sees inside it (contrast, overlap, legibility); .pptx exports a native, editable chart. Fields: vixl_reference('operations', name=['chart', 'chart-data', 'table', 'key-value-list']).",
    "brush": "Choose the brush for the medium: ink or fineliner for line art, marker for bold strokes, watercolor or airbrush for soft washes, chalk, charcoal or crayon for texture. Vary pressure and taper for life, and keep strokes on their own paint layers so they stay editable.",
"natural-color-light": """Natural color and lighting: working reference
Color is reflected illumination, not a fixed label. A foliage palette includes cool occlusion, muted local green, warm transmitted leaf edges and sky-reflecting highlights. Skin varies continuously in value, chroma and undertone; choose from observation and never infer identity from a swatch. Stone/wood/water depend on roughness, view angle and surrounding light. Use natural_palette or vixl_reference('color') natural with subject skin/foliage/sky/earth/water/stone and day/dawn/dusk/night. These are illustrative sRGB starting points, not measured material reflectances.
Plan one dominant light direction. A directional source gives approximately parallel cast shadows; point-light shadows diverge from the source; a large area light broadens penumbrae. Ambient and bounced light lift shadows; they do not erase contact occlusion. Keep a lit matte patch usually lighter than its own unlit counterpart under the same exposure; luminous objects, fill lights, local-color differences and specular reflection are exceptions. Low sun casts long shadows; noon short shadows; overcast creates broad soft modeling. Color temperature describes the illuminant, not how every painted object must look. Warm direct light can accompany cooler sky-filled shadows, but colored surroundings can reverse that relation. Simultaneous contrast means the same gray appears different on light/dark or warm/cool neighbors; inspect in context. For depth, move distant values/chroma toward the atmosphere and reduce edge contrast.
Recipes: single-source scene: choose a five-value palette, gradient background, local-color shape, clipped gradient shading, and shadow style directed away from the source. Key/fill: keep the fill weaker and broader; render both separately before blending. Rim light: duplicate the silhouette behind the subject, expand/highlight its light-facing edge, use screen/add-style compositing sparingly; avoid an even halo unless backlit. Glow: duplicate the emissive shape, blur it on its own layer, screen-blend, retain a bright small core and illuminate nearby surfaces. Keep cast shadows separate so direction and softness stay editable.
Verification: use guide-check with kind lighting, light [x,y], objects [{position:[x,y],shadow:[dx,dy],lit:'#...',shade:'#...'}]. It flags shadows pointing toward a point source and darker lit patches. These are scene-metadata heuristics; explain exceptions. Inspect grayscale and cropped final-size previews.
References: CIE International Lighting Vocabulary https://cie.co.at/e-ilv ; PBRT 4e, Light Sources and Color and Radiometry https://pbr-book.org/4ed/Light_Sources ; Josef Albers, Interaction of Color (1963), contextual color exercises. These sources establish principles, not numeric promises for the palettes.
""",
"anatomy-proportions": """Anatomy and appearance: construction reference
Use a gesture line and balance over support before contour. Torso masses are rib cage and pelvis linked by a flexible spine; shoulder girdle can move independently from the pelvis. Upper/lower arm and thigh/shin are similar but not identical lengths. Elbows and knees hinge, forearms pronate/supinate, and ball joints allow multiple axes: a 2D rig angle is not a complete anatomical joint orientation. Broad adult art convention: 7–8 heads tall; teen about 6.5–7.5; child about 5–6.5; toddler about 4–5. These overlapping ranges are construction aids, not health or appearance standards. Stylized figures can intentionally depart from them. Adult shoulder width often about 2–3 head widths. Pubic region is roughly halfway down standing height; elbow near waist, wrist near hip, fingertips near mid-thigh. Variation, pose and perspective dominate exact ratios.
Face: in a neutral front view eyes lie near half skull height (hair excluded); nose base between eyes/chin, mouth between nose/chin. The eye-to-eye gap is roughly one eye width as a starting convention, never a rule for every face. Establish cranium/jaw planes, place a centerline that wraps the form, then adapt actual asymmetry and feature spacing. Hands: palm mass plus thumb wedge and four finger arcs; knuckles and fingertips follow staggered arcs, not a straight rake. Hair is grouped volumes over the skull with parting and gravity. Clothing folds start at tension/compression/support, with thickness changing edge softness.
Represent diverse ages, body sizes, facial structure, skin tones, hair textures, mobility and clothing. Do not equate one default template with normality. Animals: use species-specific spine/ribcage/pelvis masses, limb joint direction, digitigrade/plantigrade stance and reference. Wings, fins, exoskeletons and plants require different construction; do not reuse human joint limits blindly.
Approximate adult illustration range reference (degrees, flexion coordinate conventions): elbow flexion 0–150, knee flexion 0–140, shoulder flexion 0–180, hip flexion 0–120, wrist flexion 0–80. Human variation and active/passive measurement protocols matter; these are loose illustration sanity bands, not clinical norms or medical judgments. The cited CDC study reports measured passive ranges and confidence intervals by age and sex. Check only labeled anatomical flexion measures, not arbitrary sprite rotation.
Workflow: figure-plan returns named editable head, torso, pelvis, arm and leg parts from head units and body width, plus a parts map. Apply its operations, adjust proportions from references, establish pivot locations, then use character rigging. guide-check kind anatomy accepts head_units, style realistic/stylized, joints [{name,angle}], and limbs [{name,upper,lower}]. It reports only egregious ratios and labeled flexion violations.
References: OpenStax Anatomy and Physiology 2e, chapters 7–9 (skeleton/joints) https://openstax.org/books/anatomy-and-physiology-2e/pages/9-5-types-of-body-movements ; CDC joint range-of-motion reference tables https://archive.cdc.gov/www_cdc_gov/ncbddd/jointrom/index_1715172647.html ; Andrew Loomis, Figure Drawing for All It's Worth (1943), art proportion conventions.
""",
"illustration-perspective": """Illustration style and perspective reference
Choose shape language and value hierarchy before texture. Large readable silhouettes, grouped dark/light masses, overlap and a deliberate focal contrast work across styles. Check the subject as a black silhouette at thumbnail size; avoid important appendages merging with the torso. Three grouped values usually communicate better than many unrelated midtones. Eye flow follows contrast, edges, faces and implied lines; secondary accents should lead back to the focal point.
Style recipes mapped to Vixl operations: flat = shape/pen, 3–5 palette roles, minimal gradients; line-and-wash = pen or paint with ink plus translucent watercolor/ink-wash drawn-texture; cutout = irregular shapes + paper pattern-fill and small directional shadows; painterly = paint with dry-brush/charcoal, broad masses before edges; ink = brush-pen outlines + hatching or stipple texture; pencil/crayon = paint preset plus drawn-texture and pressure/jitter, kept as separate overlays. pattern-stroke paints tiled material along a path. Inspect texture against the plain original and at intended delivery scale.
Perspective: horizon is eye level, including outside the crop. One point: front-facing planes retain parallel edges; receding edges share one vanishing point. Two point: two horizontal edge families converge to two points on one horizon. Three point: verticals also converge above/below the horizon. Wide field of view exaggerates near/far size; moving camera and changing focal length are different actions. Foreshortened limbs must shorten in projection; overlapping cross-contours and joint landmarks explain depth. Use overlap, relative size, edge softness and atmospheric contrast together. A long lens can compress depth; orthographic/isometric art deliberately avoids convergence.
Workflow: perspective-guides spec {width,height,horizon,points:1|2|3,depths:[positive distances],reference_size,reference_depth} returns a perspective grid operation and scale-by-depth sizes: size = reference_size * reference_depth / depth. Apply guide operations; place objects with a common ground plane and camera. guide-check kind perspective accepts horizon and vanishing points (only horizontal families), and objects {depth,size}; normalized size*depth should agree for equally sized objects. kind illustration accepts values [0..1] and silhouette_contrast [0..1] measured against the background. Checks are advisory and conditional, not automatic aesthetic judgments.
References: James Gurney, Imaginative Realism (2009), composition/value construction; Ernest R. Norling, Perspective Made Easy (1939), vanishing points/horizon; PBRT 4e, Cameras and Film https://pbr-book.org/4ed/Cameras_and_Film .
""",
"drawn-textures": """Drawn textures: compare before committing
Use drawn-texture target Shape preset pencil|charcoal|crayon|ink-wash|stipple|hatch|cross-hatch|scribble|spatter|dry-brush|pastel|smudge|marker. It adds a separate transparent raster overlay clipped to the rendered silhouette and retains the original vector. Set seed for reproducibility, strength 0..1, scale .1..20, jitter 0..1, pressure 0..1 and grain 0..1. Pencil/hatch jitter the line path and vary coverage per stroke; charcoal/wash use low-frequency pooled coverage; stipple scatters marks; crayon/pencil/charcoal/pastel/dry-brush interact with paper tooth; spatter flicks drops of varied size, scribble loops, smudge blends soft smears and marker lays broad felt-tip strokes. For a material rather than a medium, pattern-fill a built-in pattern (pattern-list describes each: textiles such as linen, denim and houndstooth, materials such as marble, terrazzo and leather, natural fills such as cobblestone, topographic and leopard) at low opacity over the fill. Render plain, textured and 200% detail views side by side, then verify at final size: visible tooth at 200% alone is insufficient. For editable hand-drawn outlines use paint pencil/charcoal/crayon/watercolor brush presets with pressure points; a fill overlay does not change the vector's outline geometry. Combine paper pattern-fill under a low-opacity ink wash; use clone-stamp to repeat sampled handmade marks and pattern-define to save a repeat. Inspect a 3x3 tile repeat for seams.
""",
"film-review": """Film review and performance
Before every full export, use film-preview PNG at each shot start/middle/end, at every crossfade midpoint and at extreme camera poses. time/start/end are milliseconds, matching film and timeline specs. PNG seeks directly to its requested frame, including camera crop, transitions and captions. Use shot (zero-based), or start/end, with GIF for a bounded loop (at most 300 frames/80M pixels), MP4/WebM/ZIP for a selected interval; add region [x,y,width,height] in original film pixels for a narrow crop. Do not render an entire film to check one framing change.
film-preview defaults to quality draft; explicit final uses delivery resolution. Draft caps the longest side at 640 and lowers video encoding quality. Static document shots avoid cloning/hashing timeline state each frame. Existing content-addressed disk layer caching preserves unchanged content between runs and shots; changing one layer invalidates its cache dependencies. Render only the changed shot/interval after a local change, then export the full film after approvals. Frame-parallel rendering is not enabled: memory growth and deterministic ordering must be profiled before adding it. The speedup depends on how much work is static, rasterization cost and codec; benchmark a representative draft and final interval, never assume a fixed full-film duration.
Use video-sample with explicit times or interval to produce visible labeled contact sheets; use audio-analyze for unweighted RMS dBFS, clipping, silence, spectral-flux onsets, a heuristic beat estimate and a spectrogram. Pass video event timestamps to events to measure onset timing errors. Numeric checks and spectrograms do not judge musical quality; audition exported audio with an audio-capable model/player if available.
""",
    "natural-motion": "Use anticipation (a small opposing move before effort), weight shift, curved paths, eased starts/stops and delayed secondary motion. Gravity uses y=y0+v0*t+g*t²/2 in pixels/seconds; each bounce loses velocity by restitution (0.5–0.75 is a useful start). Springs need zero initial velocity and damping; do not force an oscillating curve abruptly to its final value. Build a bouncing ball with motion recipe=bounce, then character-cycle walk, then react; inspect contact/extension/recovery poses. Use motion overlap for hair/accessories and stagger only related parts. Check motion findings for linear two-key stops and extreme acceleration; these are review heuristics, not proof of physical correctness. Constant-speed camera travel and impacts can be intentional. Sources: Thomas & Johnston, The Illusion of Life (1981); Richard Williams, The Animator's Survival Kit (2001); Newtonian projectile and damped oscillator equations.",
    "character-rigging": "Create character for a standard torso/head/eyes/brows/mouth/hair/segmented limbs set, or bind existing part layers. Save a reusable template to the document's object library with character-save; character-load gives independent parts, colors, outfit and scale. Share a character across documents as a .vixlchar package (workflow character-package, then character-place with a pose, expression and motion). Set proximal pivots, bone lengths, parent joints and angle limits; character-ik solves a two-bone chain in local pixels. Start walk/run with contact, passing and recovery poses, plant feet with IK, then offset secondary motion. Text lip-sync is approximate: use explicit timed viseme cues from aligned audio for production speech. Validate character and anatomy checks before animation.",
    "cut-paper": "Apply cut-paper to a character/group to add grain/fibers, rough silhouette edges, paper thickness shadows and shallow depth offsets. Start grain 0.04–0.08, roughness 0.3–0.6, thickness 1–3px; avoid heavy grain on small eyes/text. Use 10–12fps held poses with jitter 0–0.4px, pinned proximal limb pivots and constrained character-cycle motion. Review an image at final delivery size, plus two frames inside one hold (they should match) and across a hold boundary. Layer-depth and a slow camera move add parallax; use restrained warm lighting. See examples/build_cut_paper_demo.py.",
    "audio-composition": "Use audio-track with synthesized tones, piano/bell/bass, percussion or whoosh/pop/click/splash; sequence notes with start/duration/MIDI/velocity. Marker names synchronize timeline tracks. Keep peaks below 0dBFS: volume is linear gain, fades are milliseconds, and overlapping notes/tracks sum. WAV imports embed into the project. MP4/WebM timelines and films include the mix; export_audio writes a standalone WAV. Verify numeric peak/RMS/silence/onsets with audio analysis and listen to the result; estimated onsets/tempo do not establish perceptual musical quality.",
    "imperfection": "Imperfection (irregular, tear) makes things look made rather than computed; use it on a few chosen things, not as a finish for the whole document. Use it where the viewer expects a person, a material or an accident: a character or mascot, a sticker, a hand-inked outline, botanical shapes, cut or torn paper, a scatter of leaves or confetti. irregular {targets, seed, strength: subtle|natural|rough} wobbles outlines, jitters vertices, varies stroke weight (pressure) and drifts color, rotation, scale and position across a set; start at subtle, compare previews, then change the seed rather than stacking. tear {target, seed, edges, as: mask|clip|path} rips an edge with a paper rim and fibres, only where something is actually ripped. Do not use it on logos, icons, UI, diagrams, charts, maps or technical drawings; on anything that must align, measure or register (grids, tables, form fields, barcodes, print marks, text baselines); on text (refused); on things under about 20 px; on every layer (keep backgrounds, frames and type clean); twice (organic forms already have naturalness); or to rescue a weak design. A set of copies gets organic placement from irregular with only: [placement, color]. Pair a subtle irregular with a drawn-texture overlay or the sketch, watercolor or paper look for a hand-made finish; the hand-made look applies the wobble as a removable look, and motion recipe line-boil animates it. The result is seeded and stored: remove: true restores the exact source.",
    "scatter": "Scatter and repetition without code. scatter {target: SHAPE, source: [motif layers] or mark: {shape ...}, count or spacing, seed} fills the target's outline with Poisson-disc spaced copies (no grid look); placement: along puts them on its edge, direction normal|tangent|cone|random, anchor: base so blades and tufts grow out of the line. Vary them with rotation_jitter, scale_jitter, position_jitter, colors and tone_variation (OKLab lightness, in tones steps); exclude keeps layers clear. merge: true draws every copy as one path per tone, so hundreds of marks cost a few layers (shape motifs only); without it each copy is a layer in a group, and the layer budget applies. preset: fur grows tufts behind the edge and inner flicks above it in the target's color; the plush look does the same plus a soft gradient, hand-made wobbles outlines with irregular, and organic fur-blob is a ready furry body. Seamless patterns: pattern-scatter {source, width, height, count, seed, background, pattern: NAME} scatters on a wrap-around tile and adds wrapped copies for motifs crossing an edge, then reports seam (seamless_check: edge_error versus interior_variation); pattern-fill with that pattern and tile_variation 0.2-0.4 so the repeat does not read as a grid. Edit a motif, then pattern-scatter {target: TILE} rebuilds it with the same seed. Rows and rings: repeat and radial-repeat take rotation_step, scale_step, opacity_step and seeded rotation/scale/position/opacity jitter, and merge: true for one path. Motion: keyframes {property, sample: {fn: sin|cos|triangle|saw|square|noise, period, amplitude, offset, phase, step_ms, duration}} writes a wave as keys; motion recipe: wiggle (amount, frequency, samples) shakes about a value; recipe: line-boil (fps 8-12, variants 3) redraws vector lines with new irregular seeds per held frame for a hand-drawn boil.",
    "multi-part-objects": "Build an object from parts (a mascot, a character, a vehicle, a prop) as one group and "
    "declare it: {type: object, target: GROUP, kind: dog} (vixl_reference('capabilities', name='objects') or vixl objects lists the "
    "kinds; vixl_reference('objects', name='dog') gives a kind's parts, the parts that must touch, proportions, "
    "layering and its build block: how to draw one, where each part goes (placements such as leg at body.bottom, "
    "spread 0.15-0.85), research notes and a working example batch to adapt). The loop: reference, then "
    "vixl_apply(workflow='object-plan', request={kind: dog, height: 300, apply: true}) scaffolds the whole object as "
    "named placeholder parts that already pass the object check (CLI vixl object plan dog --height 300 --apply; apply: "
    "false returns the batch with next steps per part), refine each placeholder in place, outline, then check. Name each "
    "part you draw yourself with {type: object, "
    "action: part, target: LAYER, part: leg, side: left}, and in a side view depth: far for limbs behind the body or "
    "near for limbs in front; an object "
    "inside another (a person holding a guitar) is a sub-object, and paths such as dog/head or person/guitar/neck work "
    "wherever a layer name does. Use a subgroup per joint or sub-assembly (a head with its features, an arm with its "
    "hand), so it moves, scales and recolours as a unit; build in the group's own coordinates and use space: canvas "
    "only when placing against the scene. Parts that meet should overlap by a few pixels rather than abut, so seams do "
    "not open at small sizes, on rotation or when a joint turns: tuck a limb's end under the body and set its pivot "
    "inside the overlap. Order parts back to front as the kind's layering says (far limbs, body, near limbs, head, "
    "features). Outlines: one stroke weight for the whole object, scaled with it; outline the silhouette, not every "
    "internal seam, and keep inner lines thinner than the contour. {type: object, action: outline, target: dog} does "
    "this: outline silhouette (one generated NAME/outline layer around the union of the parts, redrawn whenever a part "
    "moves) with interior hide, thin (40% of the width, the default for animals and made things) or show; outline parts "
    "outlines every part alike; none (natural kinds) or action outline-remove restores the part strokes. outline_color "
    "and outline_width set the line (outline_lines adds a double or triple line inside it); a part takes outline: none to keep its own stroke (steam, a highlight) or parts "
    "for a full contour of its own. Open lines (whiskers, strings) keep their strokes. Keep one light direction and one "
    "shadow colour across parts. To "
    "review: vixl_document(action='inspect', object=NAME) lists the parts and the required parts still missing; "
    "vixl_render(isolate=[NAME], views=['parts'], exploded=true) shows the object assembled, exploded and part "
    "by part (isolate also takes object:KIND); compare revisions with vixl_render(action='compare', isolate=...). "
    "vixl_check runs the object check whenever the page declares objects: required parts missing or miscounted (a dog "
    "with three legs), gaps between parts the kind says touch (sampled at animation frames too, where swinging limbs "
    "come loose), proportions outside the kind's range (declare stylized: true when the exaggeration is the point), "
    "mirrored pairs that differ in size or sit on one side, parts stacked against the kind's layering, and with an "
    "outline applied part strokes showing inside the silhouette, uneven part outlines or a stale outline; each "
    "finding's hint names the build placement. In groups that are not declared objects, vixl_check(checks=[connected]) "
    "finds parts that float free; mark a part meant to float (a spark, a thrown ball) with layer-intent detached_ok. A "
    "prop held by a moving part follows it with motion recipe attach. A part drawn later (a tail added after the dog "
    "group exists) joins the object with {type: reparent, targets: [tail], into: dog}: it stays where it was drawn, and "
    "the group keeps its rotation, scale and effects. Reuse: object-save keeps an editable copy in the document and "
    "object-place inserts it again (new IDs, recolor by part); vixl_export(isolate=[NAME], path='dog.vixl') writes a "
    "portable object that object-place source= reads in another document, and an isolated SVG, PDF, PNG or PSD export "
    "writes the object alone. Exports keep the identity: SVG data-vixl-object, data-vixl-kind and data-vixl-part, "
    "PowerPoint named groups, PSD group names.",
    "looping-motion": "Loops and staggered motion are one motion operation, not hand-written keys. Design the loop first: every track returns to its t=0 value at the loop end, so make duration a whole number of periods (motion period, character-cycle period). Repeating recipes: hover (float), breathing (scale), blink (held closures), wiggle (rotation about the pivot, or any property; samples sets how many keys), orbit, bounce, line-boil (a hand-drawn redraw at fps); one operation moves many targets, and stagger (ms per target) delays each one's start: {type: motion, recipe: hover, targets: [dot-1, dot-2, dot-3], amount: 8, period: 1000, duration: 2000, stagger: 150}. In a seamless loop animate and animate-preset wrap a staggered repeat that would pass the loop end around it; a motion stagger still runs past the end, so check the seam; phase (in cycles, e.g. -0.15 per dot) offsets a target inside the loop instead. For a looping card set {type: timeline-set, loop_mode: seamless}: it warns for any track that ends away from its start, and close: true (on keyframe, animate, animate-preset or motion) appends the start value so the track closes; entrance presets then hold and play back. A spinning motif loops with {type: motion, recipe: spin, turns: 1} or, for a symmetric motif, symmetry: 12 turns it 1/12 of a circle. animate and animate-preset take repeat (or until) and period to cycle without extra operations. character-cycle gives walk, run, idle, ride and react cycles for a rigged character; keyframes writes one property's keys in one operation, or samples them from a wave with sample: {fn: sin|triangle|saw|square|noise, period, amplitude, step_ms}, and hold or step easing holds a value without keys 1 ms apart. Keep the whole message readable at frame 0, keep moving layers off text, set pivots at joints (pivot) before rotating limbs, then check vixl_check(checks=[motion]) and vixl_render(action='timeline') at the first, middle and last frames (the last should flow into the first).",
    "testing": """Testing a design: why, when, which and how
Why: you cannot look at every pixel, and a preview is a small downsampled picture. Tests measure what a glance misses (text 1 px off the canvas, contrast 4.2:1 instead of 4.5:1, gaps of 20 and 24 px, a forgotten [Label]) and they stay true while later edits pile up, so a fix in one place cannot silently break another. They are cheap, exact and repeatable; a preview is for what tests cannot judge: taste, likeness, mood. Test first, then preview.
When: 1) Before building, turn the brief into requirements and attach them as a suite (suite-set) in the first batch. 2) While building, add check=true and suites=true to vixl_apply so every batch reports its findings and failing rules with the edit. 3) Before every vixl_render, run vixl_check and the suites and fix what fails; preview only a design that passes. 4) Before export, run them once more (with sampling for animation). A failed test means change the design, never loosen the rule; set tolerances before checking, not to make a failure go away.
Choose: vixl_check covers general defects (bounds, overlap, contrast, safe_area, legibility, blanks, placeholders, fonts), composition (dead bands, margin drift, uneven rhythm, crowding, clumped scatter, and flat hierarchy, a single weight, no focal point and an unused accent as review findings) and declared objects against their kind (object), and opt-in families for the document type: deck for slides, print for print, color_vision, form with sample=worst, diagram, codes, drawing, connected and character for characters and mascots, motion for animation, guides/alignment, style for a tagged style. Starter suites (vixl_apply(workflow='resource-list', request={kind: 'suites'}); suite-use attaches one) bundle them per type: social-card, composition, slide-deck, logo, motion-loop, character, fillable-form, diagram, print-ready, accessible, delivery, palette, opaque, no-placeholders, containers. Then add rules for what only this brief requires.
Make your own: one rule per requirement, named for the requirement. Requirement to rule kind: 'title reads at thumbnail size' -> contrast {target, minimum 4.5} and text-fit {target, minimum}; 'headline clearly dominates' -> hierarchy {targets [title, subtitle, body], ratio 1.25}; 'cards evenly spaced' -> spacing {targets, axis, expected?}; 'logo 48 px from the edges' -> relation {target logo, to canvas, position inside, minimum 48}; 'caption under the photo, left-aligned' -> relation {target caption, to photo, position below, align [left], maximum 24}; 'price never overlaps the product' -> relation {position apart}; 'keep the top third quiet for the headline' -> ink {region, maximum 0.02}; 'balanced' -> balance {tolerance 0.1} or focal {target, grid thirds}; 'brand red stays brand red' -> color {point or region, expected @brand} or palette; 'exactly three bullets' -> count {target 'bullet-*', minimum 3, maximum 3}; 'headline at most 40 characters', 'must say Terms apply', 'never say free' -> text {target, max_characters 40} / {contains 'Terms apply'} / {forbid '(?i)\\bfree\\b'}; 'at most 3 fonts, images 240 ppi' -> budget {max_fonts 3, min_ppi 240} (max_ppi flags over-resolved images; max_render_ms in a rule of its own is an advisory review); 'same red and type scale as the master' -> expected/to/ratio {ref: 'master.vixl#brand.fill'} or {ref: 'master.vixl#brand:type-scale'} read the master each run (at most 8; a missing one needs review); 'transparent logo' -> alpha; any fixed value -> property or assert; a finished part that must not change -> suite-capture (unchanged and pixels rules). Use severity warning for preferences (balance, breathing room) so they need review instead of failing. Animation: add sampling {mode: sampled, count: 8} so rules hold at every sampled time; several formats: sampling {artboards: 'all', pages: 'all', comps: [...]} so rules hold on every variant. An approved design: vixl_apply(workflow='suite-infer', request={name}) proposes a tolerant suite with what each rule measured; review it before use.
Run: vixl_apply(workflow='check', request={suite: NAME or an inline suite}) returns each rule's status and measurements (failed, needs_review, passed); a rule that cannot be measured is needs_review, never a pass, and over pages a rule about a layer on another page, or limited by its pages field to other pages, is not_applicable there. vixl_apply(workflow='act', request={operations, suites}) applies a batch only if the suites still pass (repair: true first tries the built-in repairs: fit-text, contrast ink, safe-area nudge). Every result has an outcome: validated means required checks ran and passed with nothing left to review; unvalidated means nothing required was checked. Save a suite you will reuse with resource-save kind suites. Read the failing rule's numbers, fix the design, rerun, then preview. A passing suite proves only its own rules: keep them specific to the brief.""",
    "finishing": """Finishing pass: critique and polish before export
Passing checks proves a design is correct, not that it reads as designed. A finish (the look operation: glow, soft-shadow, grain, paper …) is one step of building; the finishing pass is the last step before export, after vixl_check and your suites pass: a short critique against the craft checklist, one batch of fixes and a look at real size.
1) Check composition: vixl_check(checks=["composition"]) reports dead bands, margin drift, uneven rhythm, crowding and clumped scatter as review findings, and four about hierarchy: flat_hierarchy (the largest text is under about 1.6 times the body size), single_weight (every text block in one face and weight), no_focal (the two heaviest blocks weigh about the same) and accent_unused (a page on the document's palette never draws its accent); profile='final' includes them and vixl_apply with check=true lists them with every batch. vixl_apply(workflow='repair-layout') repairs most spacing findings, least disruptive first and never adding a finding: it snaps drifting edges, re-spaces stacks, opens crowded gaps, spreads dead bands and thins clumped pattern-scatter tiles (a dry run by default; apply the plan it returns). The hierarchy findings are judgement calls: repair applies nothing and lists suggestions (raise the headline to the display step, set it in the heading role or a heavier weight, let one of two rivals lead, put @accent on the call to action). Fix the rest or waive it with a reason (layer-intent waive).
2) Critique: walk the craft checklist and write down every miss with the layer it concerns. Craft checklist:
- one focal point: one element reads first and everything else is clearly secondary;
- the type has steps: the headline is at least about twice the body size and set in a heavier weight or the heading face, not only larger;
- the accent colour is used once or twice, on what matters, never sprinkled, and it is used at least once;
- no dead band: no empty strip between blocks, or between content and an edge, that the layout did not plan;
- one left edge per column: text in a column shares one left edge (and a column of numbers or prices one right edge);
- the motif names the subject: imagery is specific to this brief (a lighthouse standing in the sea, a cup with steam), not a generic stand-in such as a sunset, a plain disc, a wave, a skyline or a stock icon;
- nothing reads as a placeholder: no stand-in shape, lorem text, default label or empty slot;
- secondary text (dates, captions, credits, footnotes) is readable at the real use size: on the phone, across the room, at print size, not only in the preview;
- glows and shadows sit only where they read as light or depth, never as a muddy halo or a smudge of dirt;
- illustrations are drawn in one consistent style (stroke weight, corners, shading) and their parts join: no gaps, cut-off shapes or broken dashes.
If the critique finds the composition itself generic and not just flawed, compare other directions before fixing details: vixl_apply(workflow='variations', request={output: 'options.png', count: 3}) renders 2-4 seeded rolls of the document on copies, returns a contact sheet with the seed, layout and palette under each tile and changes nothing; apply the chosen tile's roll step (replace: true, same seed) to keep it.
3) Fix: make every fix from the critique in one vixl_apply batch with check=true and preview=true, not a string of nudges, and keep the checks passing. That call returns the findings (every composition finding included), the preview and real-size crops of the two weakest regions: the places carrying the most findings, else the densest text and the largest empty area (check.regions says which; preview={regions: 0} leaves the crops out).
4) Look at real size: the two crops of step 3 are 1:1. For another place (the focal point, a detail) use vixl_render(region=[x, y, w, h], max_width=w, max_height=h); the default preview is reduced, and halos, blur, crowding, runts and ragged edges only show at real size.
5) Export with vixl_export; before shipping, vixl_check(profile='final') also fails on unresolved review findings.""",
    "batches": """Editing with vixl_apply: batches, steps, new pieces and workflows
A batch is atomic: every operation applies, or none, and the document autosaves. Give operations inline or operations_path (a workspace .json array or .jsonl file, errors cite the line). Use layer IDs or names from results; omit target to use the active layer; edit-layers changes every layer matching a selector in one operation; batches take up to 10,000 operations. Fields per operation: vixl_reference('operations', name=[types]); an invalid operation's error carries that schema.
Values: x/y take pixels, 'center' or a percentage like '50%'; width/height take pixels or '25%' (of the canvas, or of the parent group for grouped layers). Colors take CSS and xkcd names, #hex, rgb()/hsl()/hwb()/lab()/lch()/oklab()/oklch()/cmyk()/kelvin()/color(display-p3 …)/color-mix(), @swatch references and modifiers such as lighten(@brand, 10%) or mix(@a, @b, 30%). Common aliases (rect, circle, font_size, fill, camelCase keys, opacity '70%') are accepted and reported under 'normalized'. Opacity is 0–1 everywhere; a bare 70 is an error. Operations on existing layers take target or targets (a list: applied to each, or jointly for group/align). Path coordinates are literal local pixels; path-fit scales geometry into its box. font takes a registered font name or a role (heading, body). shape/solid/gradient/text add a layer, but with target they edit that layer in place (keeping its ID). text-set changes a whole text layer; text-style styles a phrase, range or paragraphs inside it.
Session steps run in order inside the same all-or-nothing batch: import-image {path | data_base64 | url, name, credit, license}, import-document {path | data_base64 | source, format svg|pdf|figma, svg_mode; Figma: node_id, page, rasterize_unsupported, token from FIGMA_TOKEN}, import-font {name, path | url}, font-pair {pairing (default random), mood, best_for, scope}, font-install {family, weight, role, scope}, font-cover {text, scripts} (installs Noto fallbacks for CJK, Devanagari or Thai text no font draws), style-use {name, palette} (tags a catalog style and stores its brief) and roll {purpose, mood, seed, locks, slots, replace} (rolls and applies a direction; replace re-rolls a document that already has a layout). scope: workspace makes fonts the brand.json default for new documents.
Review in the same call: check=true (or check names) returns vixl_check findings for the touched layers, every 'fix' finding, composition findings and the two weakest regions; suites=true runs the document's attached suites; preview=true (or {page, region, max_width, time, isolate, overlay, focus, regions}) returns a small PNG, plus real-size crops of the weakest regions with check; repair applies the built-in repairs (fit-text, contrast-ink, safe-area-nudge), each kept only if its finding resolves. dry_run validates, checks and previews without saving. verbose (or detail compact|full) returns changed values or before/after snapshots.
New piece: vixl_apply(create={path, size | width+height, purpose, background, font_pairing, layout {name, slots…}, style, look, seed, variety}, operations=[…], exports=[…]) runs create → fonts → layout → style → look → operations → check → preview → save → exports atomically; strict=true fails on 'fix' findings.
Workflows: vixl_apply(workflow=ACTION, request={…}) runs production actions: suites (check, act, suite-use, suite-infer), resources (resource-list/get/save), libraries, branches and groups, check-all, replace-across, pipeline-run (saved, resumable multi-step runs over many documents), data-sync, bulk-upgrade, merge-impose (print sheets from a CSV), form-fill, repair-layout, variations (a contact sheet of seeded rolls to choose from), adapt-sizes, film and lyric video, logo-package, brand-board and more (vixl_reference('workflows')). Long jobs: submit with start=true, then status.
Pages and slides are page operations (preview page='all'; export .pdf, .pptx or .html); forms are field layers (check form; export fillable=true, or values= to fill); hand drawings are drawing operations checked with check drawing; a design derived from another is a live link layer.""",
    "checks": """Checks: what vixl_check finds
Default checks: bounds (content cut off by the canvas), overlap (text over text), contrast (WCAG text contrast 4.5:1, or 3:1 for 24px+ text or 18.66px+ bold), safe_area (content outside a safe area or inside avoid zones), legibility (text too small at thumbnail width), blanks and placeholders (leftover template copy: lorem ipsum, TODO, 'Headline here', unresolved ${name}), fonts, composition (dead bands, margin drift, uneven rhythm, crowding under a rule or heading, clumped scatters, flat type hierarchy, one weight, no focal point, an unused accent; review findings with code, region, value and threshold) and, when the page declares objects, object (each object against its kind: missing or miscounted parts, gaps between parts that must touch, also at animation frames, proportions, mirrored pairs and back-to-front layering; the hint names the kind's build placement).
Opt-in: print (ink coverage, low-resolution images, tiny type in points, backgrounds short of the bleed), color_vision (contrast that collapses for colour-blind readers), deck (every page, title placement, type scale, words per page, projected type size, speaker notes), form (field names, overlap, tab order, sizes, contrast; sample='worst' or a CSV finds overflowing values), style (the document's style tag rule by rule), connected (parts of a group that float free; declared objects are left to object), cost (layers that take over 10x the median to draw, and why), accessibility (contrast and color_vision plus alt text, language, small text, colour-only charts, reading order), drawing, diagram, flow, codes, motion, character, captions, links, guides, alignment, brand, empty, notes, min_font, words, type_scale, title_position.
Each finding has a stable rule ID (bounds.text-overflow, contrast.text-contrast …), layer_ids, its box or region in document pixels, measured actual versus expected, a severity and an action: fix (needs a design change), review (look and decide) or informational (expected, such as a crop marked with layer-intent allow_crop). by_action indexes them; fix findings carry a repair suggestion of canonical operations to dry-run with vixl_apply (repair=true applies the built-in ones). Waived findings (layer-intent waive, the waiver operation) stay listed as informational with their reason. outcome separates validation (fix findings) from review; a profile (draft, review, final or the workspace's .vixl-checks.json) picks checks and suites and its fail_on decides passed. artboards, pages and comps check every variant in one call; offset and limit page the findings.
Other actions: validate (rules and saved suites against a profile), measure (rendered RGBA samples, averages, histograms, layer contrast), spacing (pass/fail for equal gaps or balance around an object), spatial (relations, margins, grid and guide offsets, hit tests, free regions, snap operations) and pixels (a pixel layer as character rows). Suites (your own rules) run with vixl_apply(workflow='check') or suites=true on a batch; vixl_reference('testing') explains them.""",
    "exports": """Exports: vixl_export
The extension picks the format: PNG, JPEG, WEBP, TIFF, AVIF, SVG, PDF, ICO, HTML, PPTX, PSD (or .vixl with isolate: a portable object document). Full size by default; scale, dpi and profile resize. color_space='cmyk' separates JPEG, TIFF and PDF for print (icc_profile for press accuracy, else device-naive GCR with black_generation and ink_limit); proof and simulate preview print and colour-blind views. PDF is vector by default, CMYK too: real text, vector shapes and DeviceCMYK colours, images only for effects (raster_fallbacks says which); pdf_content='raster' writes one image per page; print sizes measure exactly trim + bleed with TrimBox and BleedBox. A multi-page document exports every shown page to PDF, PowerPoint (editable slides with speaker notes) or HTML (a self-contained presentation: keyboard, overview, transitions, speaker view; presenter options); pages= picks pages. fillable writes PDF form fields; values fills them (fill_mode flatten or editable). PNG and other alpha formats are RGB when opaque; alpha='keep' forces RGBA, 'flatten' composites onto background. svg_policy='strict' rejects raster fallbacks. PSD is a layered handoff (one pixel layer per layer, groups as layer groups, text as pixels). TTF, OTF and WOFF (WOFF2 with brotli) write the font drawn in the document (font-design, font-grid, font-glyph). isolate exports only some layers or objects, cropped to their ink. time exports one timeline frame. Exports refuse existing files unless overwrite=true and run no design checks: vixl_check first. check=true or spec (a delivery preset such as print-letter-bleed, instagram-feed or web-banner, or fields like max_bytes, pages, bleed, fonts_embedded, color, dpi, alpha) reads the written file back and reports export_check findings (PDF boxes, embedded fonts, colour, ink; raster size, dpi, ICC, alpha; PowerPoint text and charts; HTML/SVG external URLs).
Other kinds: batch (targets=[{path, …options}], defaults: several sizes, formats, artboards or documents in one call, all validated first); timeline (.gif .apng .webp .mp4 .webm, a sprite sheet or PNG-sequence .zip: fps, scale, colors, dither, poster, target_bytes or preset chat|web|email fit a size budget; MP4/WebM take preset draft|final. Lottie .json/.lottie/.tgs keep Bezier easing as curves and linked instances as time-remapped precompositions, report raster fallbacks, and strict refuses them; TGS enforces sticker limits); animation (saved frame-by-frame animation and named animations: nearest sampling keeps pixel art crisp); audio (.wav mix of the audio tracks); icons (a folder: web favicon set, apple, android, windows or all); character (a .vixl character library for character-load). The kind follows the extension and the document (a .gif of a document with only saved frames is an animation); pass kind to choose.""",
}


# Tool profiles: the tools a host application offers its own model, described in the host's terms (endpoints, not
# MCP tools). ``vixl host`` serves them at GET /catalog/tools?profile=NAME, with each tool's input schema derived at
# request time from the operation, compose, check and export schemas (``input_schema_ref`` names which).
TOOL_PROFILES = {
    "studio": (
        {"name": "list_documents", "method": "GET", "path": "/w/{ws}/documents", "input_schema_ref": "documents",
         "description": "List the design documents in this workspace with their ids and revisions."},
        {"name": "create_document", "method": "POST", "path": "/w/{ws}/documents", "input_schema_ref": "create",
         "description": "Create an empty design document from a named size, a width and height, a purpose (poster, "
                        "social, slides, logo) or a brief; it gets a palette, a font pairing and design defaults."},
        {"name": "get_document", "method": "GET", "path": "/w/{ws}/documents/{id}", "input_schema_ref": "document",
         "description": "Read a document: canvas, revision and every layer with its id, name, type and bounds."},
        {"name": "describe_operations", "method": "GET", "path": "/catalog/operations", "input_schema_ref":
         "operation_names", "description": "The exact fields of up to 20 operation types, before using them."},
        {"name": "apply_operations", "method": "POST", "path": "/w/{ws}/documents/{id}/operations",
         "input_schema_ref": "operations",
         "description": "Change a document with a batch of operations (add text, shapes, images, layouts, styles, "
                        "effects). The batch applies all or nothing; set check to review the result and "
                        "if_revision to refuse a stale edit."},
        {"name": "compose_document", "method": "POST", "path": "/w/{ws}/documents/{id}/compose",
         "input_schema_ref": "compose",
         "description": "Build a whole piece in one call: layout with its copy, style, look, extra operations and a "
                        "design check. It replaces the document's content; dry_run previews without saving."},
        {"name": "preview_document", "method": "POST", "path": "/w/{ws}/documents/{id}/preview",
         "input_schema_ref": "preview",
         "description": "A PNG preview of the document, one page, every page as a contact sheet, or a region, "
                        "within a size and byte budget. Look at it before exporting."},
        {"name": "check_document", "method": "POST", "path": "/w/{ws}/documents/{id}/check",
         "input_schema_ref": "check",
         "description": "Run the design checks: each finding has a rule, a severity, an action (fix, review or "
                        "informational), a message and the layer it is about. Fix every 'fix' finding."},
        {"name": "export_document", "method": "POST", "path": "/w/{ws}/documents/{id}/exports",
         "input_schema_ref": "export",
         "description": "Export to PNG, JPEG, SVG, PDF, PowerPoint and other formats as a job; follow the job, then "
                        "download the file."},
        {"name": "get_job", "method": "GET", "path": "/jobs/{job_id}", "input_schema_ref": "job",
         "description": "How far an export or a long call has got, its error if it failed, and where to download "
                        "the result."},
        {"name": "add_image", "method": "POST", "path": "/w/{ws}/documents/{id}/assets", "input_schema_ref": "asset",
         "description": "Place an image the user supplied (the request body is the image bytes) as a new layer, "
                        "with its credit and license."},
        {"name": "browse_catalog", "method": "GET", "path": "/catalog/{kind}", "input_schema_ref": "catalog",
         "description": "Look up what to design with: sizes, layouts, palettes, typefaces and pairings, styles, "
                        "looks, checks, or a guide for a brief (what to make and how)."},
    ),
}


@lru_cache(maxsize=1)
def motif_registry():
    """Every motif theme: ``{name: {title, keywords, moods, elements}}``."""
    return json.loads(MOTIFS_FILE.read_text(encoding="utf-8"))["themes"]


def _plain(text):
    folded = unicodedata.normalize("NFKD", str(text)).encode("ascii", "ignore").decode("ascii")
    return " " + " ".join(re.findall(r"[a-z0-9]+", folded.lower())) + " "


def phrases(brief, words):
    """The ``words`` (single words or phrases) that occur in ``brief`` as whole words, accents and case ignored."""
    text = _plain(brief)
    return [word for word in words if _plain(word) in text]


def motifs(brief):
    """The motif themes a free-text brief implies, best match first, each with the keywords it matched and the
    palette moods the theme implies."""
    found = []
    for index, (name, theme) in enumerate(motif_registry().items()):
        hits = phrases(brief, theme["keywords"])
        if hits:
            found.append((-sum(len(_plain(w).split()) for w in hits), index, name, hits))
    return [{"theme": name, "title": motif_registry()[name]["title"], "matched": hits,
             "moods": list(motif_registry()[name].get("moods", [])),
             "elements": json.loads(json.dumps(motif_registry()[name]["elements"]))}
            for _, _, name, hits in sorted(found)]
